import React, { useState, useEffect } from 'react';
import i18n from 'i18next';

// Define the translation resources with all the text for the app.
const resources = {
  en: {
    translation: {
      "app_title": "Fertilizer Recommendation System",
      "app_header": "RECOMMENDING BEST FERTILIZER FOR YOUR CROP",
      "change_language": "Change Language",
      "temperature_label": "Temperature (C):",
      "humidity_label": "Humidity (%):",
      "moisture_label": "Moisture (%):",
      "soil_type_label": "Soil Type:",
      "crop_type_label": "Crop Type:",
      "nitrogen_label": "Nitrogen (PPM):",
      "potassium_label": "Potassium (PPM):",
      "phosphorous_label": "Phosphorous (PPM):",
      "maharashtra_n_label": "Nitrogen (kg/ha):",
      "maharashtra_p_label": "Phosphorus (kg/ha):",
      "maharashtra_k_label": "Potassium (kg/ha):",
      "maharashtra_ph_label": "pH Value:",
      "maharashtra_rainfall_label": "Rainfall (mm):",
      "maharashtra_temp_label": "Temperature (C):",
      "maharashtra_district_label": "District Name:",
      "maharashtra_soil_label": "Soil Color:",
      "predict_button": "Predict",
      "result_header": "Recommended Fertilizer IS:",
      "default_result": "Fill the form and click 'Predict'",
      "language_en": "English",
      "language_pa": "ਪੰਜਾਬੀ",
      "language_hi": "हिन्दी",
      "soil_black": "Black",
      "soil_clayey": "Clayey",
      "soil_loamy": "Loamy",
      "soil_sandy": "Sandy",
      "soil_red": "Red",
      "crop_barley": "Barley",
      "crop_maize": "Maize",
      "crop_wheat": "Wheat",
      "crop_rice": "Rice",
      "crop_cotton": "Cotton",
      "select_area": "Select Your Crop Area:",
      "area_general": "General Model (Global)",
      "area_maharashtra": "Maharashtra (State Specific)"
    }
  },
  pa: {
    translation: {
      "app_title": "ਖਾਦ ਦੀ ਸਿਫ਼ਾਰਸ਼ ਪ੍ਰਣਾਲੀ",
      "app_header": "ਤੁਹਾਡੀ ਫਸਲ ਲਈ ਸਭ ਤੋਂ ਵਧੀਆ ਖਾਦ ਦੀ ਸਿਫਾਰਸ਼ ਕਰ ਰਿਹਾ ਹੈ",
      "change_language": "ਭਾਸ਼ਾ ਬਦਲੋ",
      "temperature_label": "ਤਾਪਮਾਨ (C):",
      "humidity_label": "ਨਮੀ (%):",
      "moisture_label": "ਨਮੀ (%):",
      "soil_type_label": "ਮਿੱਟੀ ਦੀ ਕਿਸਮ:",
      "crop_type_label": "ਫਸਲ ਦੀ ਕਿਸਮ:",
      "nitrogen_label": "ਨਾਈਟ੍ਰੋਜਨ (PPM):",
      "potassium_label": "ਪੋਟਾਸ਼ੀਅਮ (PPM):",
      "phosphorous_label": "ਫਾਸਫੋਰਸ (PPM):",
      "maharashtra_n_label": "ਨਾਈਟ੍ਰੋਜਨ (kg/ha):",
      "maharashtra_p_label": "ਫਾਸਫੋਰਸ (kg/ha):",
      "maharashtra_k_label": "ਪੋਟਾਸ਼ੀਅਮ (kg/ha):",
      "maharashtra_ph_label": "pH ਮੁੱਲ:",
      "maharashtra_rainfall_label": "ਮੀਂਹ (mm):",
      "maharashtra_temp_label": "ਤਾਪਮਾਨ (C):",
      "maharashtra_district_label": "ਜ਼ਿਲ੍ਹੇ ਦਾ ਨਾਮ:",
      "maharashtra_soil_label": "ਮਿੱਟੀ ਦਾ ਰੰਗ:",
      "predict_button": "ਅਨੁਮਾਨ ਲਗਾਓ",
      "result_header": "ਸਿਫਾਰਸ਼ ਕੀਤੀ ਖਾਦ ਹੈ:",
      "default_result": "ਫਾਰਮ ਭਰੋ ਅਤੇ 'ਅਨੁਮਾਨ ਲਗਾਓ' 'ਤੇ ਕਲਿੱਕ ਕਰੋ",
      "language_en": "ਅੰਗਰੇਜ਼ੀ",
      "language_pa": "ਪੰਜਾਬੀ",
      "language_hi": "ਹਿੰਦੀ",
      "soil_black": "ਕਾਲੀ",
      "soil_clayey": "ਚੀਕਣੀ",
      "soil_loamy": "ਰੇਤਲੀ",
      "soil_sandy": "ਰੇਤਲੀ",
      "soil_red": "ਲਾਲ",
      "crop_barley": "ਜੌਂ",
      "crop_maize": "ਮੱਕੀ",
      "crop_wheat": "ਕਣਕ",
      "crop_rice": "ਚੌਲ",
      "crop_cotton": "ਕਪਾਹ",
      "select_area": "ਆਪਣਾ ਫਸਲੀ ਖੇਤਰ ਚੁਣੋ:",
      "area_general": "ਜਨਰਲ ਮਾਡਲ (ਗਲੋਬਲ)",
      "area_maharashtra": "ਮਹਾਰਾਸ਼ਟਰ (ਰਾਜ ਵਿਸ਼ੇਸ਼)"
    }
  },
  hi: {
    translation: {
      "app_title": "उर्वरक सिफारिश प्रणाली",
      "app_header": "आपकी फसल के लिए सर्वोत्तम उर्वरक की सिफारिश",
      "change_language": "भाषा बदलें",
      "temperature_label": "तापमान (C):",
      "humidity_label": "आर्द्रता (%):",
      "moisture_label": "नमी (%):",
      "soil_type_label": "मिट्टी का प्रकार:",
      "crop_type_label": "फसल का प्रकार:",
      "nitrogen_label": "नाइट्रोजन (PPM):",
      "potassium_label": "पोटेशियम (PPM):",
      "phosphorous_label": "फास्फोरस (PPM):",
      "maharashtra_n_label": "नाइट्रोजन (kg/ha):",
      "maharashtra_p_label": "फास्फोरस (kg/ha):",
      "maharashtra_k_label": "पोटेशियम (kg/ha):",
      "maharashtra_ph_label": "पीएच मान:",
      "maharashtra_rainfall_label": "वर्षा (mm):",
      "maharashtra_temp_label": "तापमान (C):",
      "maharashtra_district_label": "जिले का नाम:",
      "maharashtra_soil_label": "मिट्टी का रंग:",
      "predict_button": "भविष्यवाणी करें",
      "result_header": "अनुशंसित उर्वरक है:",
      "default_result": "फ़ॉर्म भरें और 'भविष्यवाणी करें' पर क्लिक करें",
      "language_en": "अंग्रेज़ी",
      "language_pa": "पंजाबी",
      "language_hi": "हिन्दी",
      "soil_black": "काली",
      "soil_clayey": "चिकनी",
      "soil_loamy": "दोमट",
      "soil_sandy": "रेतीली",
      "soil_red": "लाल",
      "crop_barley": "जौ",
      "crop_maize": "मक्का",
      "crop_wheat": "गेहूं",
      "crop_rice": "चावल",
      "crop_cotton": "कपास",
      "select_area": "अपना फसल क्षेत्र चुनें:",
      "area_general": "सामान्य मॉडल (वैश्विक)",
      "area_maharashtra": "महाराष्ट्र (राज्य विशिष्ट)"
    }
  }
};

// Initialize i18n
i18n.init({
  compatibilityJSON: 'v3',
  resources,
  lng: 'en', // Set a default language
  fallbackLng: 'en',
  interpolation: {
    escapeValue: false
  }
});

// --- ENCODING MAPPINGS ---
// Used for the General Model (existing API endpoint: /predict)
const generalSoilTypeMapping = {
  'Black': 0,
  'Clayey': 1,
  'Loamy': 2,
  'Sandy': 3,
  'Red': 4
};

const generalCropTypeMapping = {
  'Barley': 0,
  'Maize': 1,
  'Wheat': 2,
  'Rice': 3,
  'Cotton': 4
};

// Used for the Maharashtra Model (new API endpoint: /predict_maharashtra)
const maharashtraSoilColorMapping = {
  'Black': 0,
  'Red': 1,
  'Laterite': 2,
  'Alluvial': 3,
  'Brown': 4,
  'Grey': 5
};

const maharashtraDistrictMapping = {
  'Pune': 0,
  'Nagpur': 1,
  'Nashik': 2,
  'Aurangabad': 3,
  'Amravati': 4
};

// --- APP MODE STATE MACHINE ---
const AppMode = {
  HOME: 'HOME',
  GENERAL: 'GENERAL',
  MAHARASHTRA: 'MAHARASHTRA'
};

const App = () => {
  const [currentLanguage, setCurrentLanguage] = useState(i18n.language);
  const [appMode, setAppMode] = useState(AppMode.HOME);
  const [inputs, setInputs] = useState({
    temperature: '', humidity: '', moisture: '', soilType: 'Black', cropType: 'Barley',
    nitrogen: '', potassium: '', phosphorous: '', // General Model NPK
    // Maharashtra Model Inputs
    maharashtraN: '', maharashtraP: '', maharashtraK: '', maharashtraPh: '',
    maharashtraRainfall: '', maharashtraTemp: '', maharashtraDistrict: 'Pune',
    maharashtraSoilColor: 'Black', maharashtraCrop: 'Rice'
  });
  const [result, setResult] = useState(i18n.t('default_result'));
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    const handleLanguageChange = (lng) => {
      setCurrentLanguage(lng);
      setResult(i18n.t('default_result'));
    };
    i18n.on('languageChanged', handleLanguageChange);
    return () => { i18n.off('languageChanged', handleLanguageChange); };
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setInputs(prevInputs => ({ ...prevInputs, [name]: value, }));
  };

  const handleLanguageChange = (e) => {
    i18n.changeLanguage(e.target.value);
  };

  // --- PREDICTION LOGIC ---

  const handleGeneralPredict = async () => {
    setIsLoading(true);
    setResult("Loading...");

    const dataToSend = {
      temperature: inputs.temperature,
      humidity: inputs.humidity,
      moisture: inputs.moisture,
      soilType: generalSoilTypeMapping[inputs.soilType],
      cropType: generalCropTypeMapping[inputs.cropType],
      nitrogen: inputs.nitrogen,
      potassium: inputs.potassium,
      phosphorous: inputs.phosphorous,
    };
    
    const apiUrl = 'http://127.0.0.1:5000/predict';

    try {
      const response = await fetch(apiUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', },
        body: JSON.stringify(dataToSend),
      });

      if (!response.ok) throw new Error('Network response was not ok');

      const data = await response.json();
      setResult(data.recommendation);
    } catch (error) {
      console.error('Fetch error (General):', error);
      setResult("Error: Could not get a recommendation.");
    } finally {
      setIsLoading(false);
    }
  };

  const handleMaharashtraPredict = async () => {
    setIsLoading(true);
    setResult("Loading...");

    const dataToSend = {
      N: inputs.maharashtraN,
      P: inputs.maharashtraP,
      K: inputs.maharashtraK,
      pH: inputs.maharashtraPh,
      Rainfall: inputs.maharashtraRainfall,
      Temperature: inputs.maharashtraTemp,
      District_Name: maharashtraDistrictMapping[inputs.maharashtraDistrict],
      Soil_Color: maharashtraSoilColorMapping[inputs.maharashtraSoilColor],
      Crop: generalCropTypeMapping[inputs.maharashtraCrop], // Reusing Crop Mapping
    };
    
    const apiUrl = 'http://127.0.0.1:5000/predict_maharashtra';

    try {
      const response = await fetch(apiUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', },
        body: JSON.stringify(dataToSend),
      });

      if (!response.ok) throw new Error('Network response was not ok');

      const data = await response.json();
      setResult(data.recommendation);
    } catch (error) {
      console.error('Fetch error (Maharashtra):', error);
      setResult("Error: Could not get a Maharashtra recommendation.");
    } finally {
      setIsLoading(false);
    }
  };


  // --- UI RENDERING FUNCTIONS ---

  const inputClass = "w-full p-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-green-500";
  const labelClass = "text-sm md:text-base font-semibold text-gray-700";
  const buttonClass = "bg-green-600 hover:bg-green-700 text-white font-bold py-3 px-12 rounded-full transition-colors duration-300 shadow-lg text-lg focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-offset-2 disabled:opacity-50 disabled:cursor-not-allowed";

  const renderGeneralForm = () => (
    <>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Left Column (Sensors/General NPK) */}
        <div className="space-y-4">
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('temperature_label')}</label>
            <input type="number" name="temperature" value={inputs.temperature} onChange={handleInputChange} className={inputClass} />
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('humidity_label')}</label>
            <input type="number" name="humidity" value={inputs.humidity} onChange={handleInputChange} className={inputClass} />
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('moisture_label')}</label>
            <input type="number" name="moisture" value={inputs.moisture} onChange={handleInputChange} className={inputClass} />
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('nitrogen_label')}</label>
            <input type="number" name="nitrogen" value={inputs.nitrogen} onChange={handleInputChange} className={inputClass} />
          </div>
        </div>

        {/* Right Column (Types/NPK) */}
        <div className="space-y-4">
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('soil_type_label')}</label>
            <select name="soilType" value={inputs.soilType} onChange={handleInputChange} className={inputClass}>
              {Object.keys(generalSoilTypeMapping).map(key => <option key={key} value={key}>{i18n.t(`soil_${key.toLowerCase()}`)}</option>)}
            </select>
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('crop_type_label')}</label>
            <select name="cropType" value={inputs.cropType} onChange={handleInputChange} className={inputClass}>
              {Object.keys(generalCropTypeMapping).map(key => <option key={key} value={key}>{i18n.t(`crop_${key.toLowerCase()}`)}</option>)}
            </select>
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('potassium_label')}</label>
            <input type="number" name="potassium" value={inputs.potassium} onChange={handleInputChange} className={inputClass} />
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('phosphorous_label')}</label>
            <input type="number" name="phosphorous" value={inputs.phosphorous} onChange={handleInputChange} className={inputClass} />
          </div>
        </div>
      </div>
      
      <div className="mt-8 flex justify-center">
        <button onClick={handleGeneralPredict} disabled={isLoading} className={buttonClass}>
          {isLoading ? 'Predicting...' : i18n.t('predict_button')}
        </button>
      </div>
    </>
  );

  const renderMaharashtraForm = () => (
    <>
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Left Column */}
        <div className="space-y-4">
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('maharashtra_n_label')}</label>
            <input type="number" name="maharashtraN" value={inputs.maharashtraN} onChange={handleInputChange} className={inputClass} />
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('maharashtra_p_label')}</label>
            <input type="number" name="maharashtraP" value={inputs.maharashtraP} onChange={handleInputChange} className={inputClass} />
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('maharashtra_k_label')}</label>
            <input type="number" name="maharashtraK" value={inputs.maharashtraK} onChange={handleInputChange} className={inputClass} />
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('maharashtra_ph_label')}</label>
            <input type="number" name="maharashtraPh" value={inputs.maharashtraPh} onChange={handleInputChange} className={inputClass} />
          </div>
        </div>

        {/* Right Column */}
        <div className="space-y-4">
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('maharashtra_rainfall_label')}</label>
            <input type="number" name="maharashtraRainfall" value={inputs.maharashtraRainfall} onChange={handleInputChange} className={inputClass} />
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('maharashtra_temp_label')}</label>
            <input type="number" name="maharashtraTemp" value={inputs.maharashtraTemp} onChange={handleInputChange} className={inputClass} />
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('maharashtra_district_label')}</label>
            <select name="maharashtraDistrict" value={inputs.maharashtraDistrict} onChange={handleInputChange} className={inputClass}>
              {Object.keys(maharashtraDistrictMapping).map(key => <option key={key} value={key}>{key}</option>)}
            </select>
          </div>
          <div className="flex flex-col space-y-1">
            <label className={labelClass}>{i18n.t('maharashtra_soil_label')}</label>
            <select name="maharashtraSoilColor" value={inputs.maharashtraSoilColor} onChange={handleInputChange} className={inputClass}>
              {Object.keys(maharashtraSoilColorMapping).map(key => <option key={key} value={key}>{key}</option>)}
            </select>
          </div>
        </div>
      </div>
      
      <div className="mt-8 flex justify-center">
        <button onClick={handleMaharashtraPredict} disabled={isLoading} className={buttonClass}>
          {isLoading ? 'Predicting...' : i18n.t('predict_button')}
        </button>
      </div>
    </>
  );

  const renderHomeUI = () => (
    <div className="flex flex-col items-center justify-center space-y-8 p-10">
      <h2 className="text-xl md:text-2xl font-semibold text-gray-700">{i18n.t('select_area')}</h2>
      <div className="flex flex-col sm:flex-row gap-6 w-full max-w-sm">
        <button
          onClick={() => setAppMode(AppMode.GENERAL)}
          className="flex-1 bg-blue-500 hover:bg-blue-600 text-white font-bold py-4 px-6 rounded-lg shadow-md transition-all duration-200"
        >
          {i18n.t('area_general')}
        </button>
        <button
          onClick={() => setAppMode(AppMode.MAHARASHTRA)}
          className="flex-1 bg-orange-500 hover:bg-orange-600 text-white font-bold py-4 px-6 rounded-lg shadow-md transition-all duration-200"
        >
          {i18n.t('area_maharashtra')}
        </button>
      </div>
    </div>
  );

  const renderCurrentContent = () => {
    switch (appMode) {
      case AppMode.HOME:
        return renderHomeUI();
      case AppMode.GENERAL:
        return renderGeneralForm();
      case AppMode.MAHARASHTRA:
        return renderMaharashtraForm();
      default:
        return renderHomeUI();
    }
  };

  const getHeaderTitle = () => {
    switch (appMode) {
      case AppMode.GENERAL:
        return i18n.t('app_header');
      case AppMode.MAHARASHTRA:
        return i18n.t('area_maharashtra') + " Recommendation";
      default:
        return i18n.t('select_area');
    }
  };

  return (
    <div className="min-h-screen bg-cover bg-center" style={{backgroundImage: "url('https://placehold.co/1920x1080/4F4/green?text=Plant+Background')"}}>
      <div className="absolute inset-0 bg-black opacity-60"></div>
      
      {/* App Title: Team IOTA */}
      <h1 className="relative z-20 text-4xl font-extrabold text-white text-center pt-8 tracking-wider">
        TEAM IOTA
      </h1>
      
      {/* Main Content Card */}
      <div className="relative z-10 flex flex-col items-center justify-center min-h-[calc(100vh-100px)] p-4 md:p-8">
        
        {/* Language Switcher */}
        <div className="w-full max-w-2xl flex justify-end items-center mb-4 relative z-20">
          {appMode !== AppMode.HOME && (
             <button
                onClick={() => setAppMode(AppMode.HOME)}
                className="bg-gray-700 hover:bg-gray-800 text-white text-sm font-bold py-2 px-4 rounded-full transition-colors duration-300 shadow-lg mr-2"
              >
                ← Back to Home
              </button>
          )}
          <label htmlFor="language-select" className="text-white font-medium hidden md:block mr-2">{i18n.t('change_language')}:</label>
          <select 
            id="language-select"
            value={currentLanguage}
            onChange={handleLanguageChange}
            className="p-2 border border-gray-300 rounded-lg shadow-sm text-gray-700 focus:outline-none focus:ring-2 focus:ring-green-500"
          >
            <option value="en">{i18n.t('language_en')}</option>
            <option value="pa">{i18n.t('language_pa')}</option>
            <option value="hi">{i18n.t('language_hi')}</option>
          </select>
        </div>
        
        {/* Form/Home Container */}
        <div className="bg-white rounded-3xl shadow-xl p-6 md:p-12 max-w-2xl w-full">
          {/* Header Section */}
          <div className="flex justify-center mb-6 border-b pb-4">
            <h2 className="text-2xl font-extrabold text-gray-800 tracking-wide text-center">
              {getHeaderTitle()}
            </h2>
          </div>

          {renderCurrentContent()}
        </div>

        {/* Result Section (Only shown for Form Modes) */}
        {(appMode === AppMode.GENERAL || appMode === AppMode.MAHARASHTRA) && (
          <div className="mt-8 bg-white rounded-3xl shadow-xl p-6 w-full max-w-2xl text-center">
            <h3 className="text-xl md:text-2xl font-bold text-gray-800 mb-2">
              {i18n.t('result_header')}
            </h3>
            <p className="text-3xl md:text-4xl font-extrabold text-green-700">
              {result}
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

export default App;
